// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {StaxLPStaking} from "../src/StaxLPStaking.sol";

contract InvMutTest is Test {
    StaxLPStaking c;
    function setUp() public { c = new StaxLPStaking(address(this), address(this)); }
    function testRegression_property() public {

        c.addReward(address(0x123));

        address newOwner = address(0xBEEF);
        c.transferOwnership(newOwner);

        address ownerAfter = c.owner();
        assertTrue(ownerAfter == newOwner, "Owner should have changed to newOwner");
    }
}
